importScripts('vendor/sql-wasm.js','data.js');
let SQL;
const ready=initSqlJs({locateFile:()=> 'vendor/sql-wasm.wasm'}).then(s=>{SQL=s;postMessage({ready:true});});
onmessage=async ({data})=>{await ready; const db=new SQL.Database(); try {db.run(seed);db.run('PRAGMA query_only = ON;');let result=null;for(const stmt of db.iterateStatements(data.sql)){if(result)throw new Error('Выполните только один SELECT-запрос.');const columns=stmt.getColumnNames();if(!columns.length)throw new Error('Нужен SELECT-запрос, который возвращает таблицу.');const values=[];while(stmt.step()){values.push(stmt.get());if(values.length>1000)throw new Error('Слишком много строк. Используйте LIMIT 1000.');}result={columns,values};}if(!result)throw new Error('Напишите SELECT-запрос.');let correct=null;if(data.check){const t=tasks[data.task-1];const expected=db.exec(t.answer)[0];const normalize=r=>r.values.map(v=>JSON.stringify(v));let a=normalize(result),b=normalize(expected);if(!t.ordered){a.sort();b.sort();}correct=result.columns.length===expected.columns.length&&JSON.stringify(a)===JSON.stringify(b);if(/ AS /i.test(t.answer))correct=correct&&JSON.stringify(result.columns)===JSON.stringify(expected.columns);}postMessage({result,correct,id:data.id});}catch(e){postMessage({error:e.message,id:data.id});}finally{db.close();}};
